from jsonb_to_recordset($q$[{"id":7239,"materia":"civ","nivel":0,"enunciado":"Luana completou 18 anos hoje. A partir de agora, pelo Código Civil, ela:","opcoes":["Pode praticar sozinha todos os atos da vida civil","Ainda precisa da assinatura dos pais em contratos","Só pode votar","Continua relativamente incapaz"],"explicacao":"Art. 5º do Código Civil."},{"id":7240,"materia":"civ","nivel":1,"enunciado":"Pedro tem 16 anos. Pelo Código Civil, ele é:","opcoes":["Relativamente incapaz","Absolutamente incapaz","Plenamente capaz","Emancipado automaticamente"],"explicacao":"Art. 4º, I: maiores de 16 e menores de 18."},{"id":7241,"materia":"civ","nivel":0,"enunciado":"O nome de uma pessoa é protegido pelo Código Civil como:","opcoes":["Direito da personalidade","Bem público","Contrato","Propriedade comercial"],"explicacao":"Arts. 16 a 19 do Código Civil."},{"id":7242,"materia":"civ","nivel":1,"enunciado":"Carla empresta um livro a uma amiga, de graça, para que ela o devolva depois. Esse contrato é o de:","opcoes":["Comodato","Mútuo","Locação","Doação"],"explicacao":"Empréstimo gratuito de coisa que não se consome."},{"id":7243,"materia":"civ","nivel":1,"enunciado":"Rui empresta R$ 1.000 a um colega, que vai devolver a mesma quantia depois. Esse contrato é o de:","opcoes":["Mútuo","Comodato","Locação","Doação"],"explicacao":"Empréstimo de coisa que se consome, como dinheiro."},{"id":7244,"materia":"civ","nivel":0,"enunciado":"Alugar um apartamento para morar é um contrato de:","opcoes":["Locação","Doação","Comodato","Mútuo"],"explicacao":"Há pagamento pelo uso do imóvel."},{"id":7245,"materia":"civ","nivel":0,"enunciado":"Quem transfere um bem a outra pessoa de graça, por vontade própria, faz uma:","opcoes":["Doação","Locação","Compra e venda","Permuta"],"explicacao":"Art. 538 do Código Civil."},{"id":7246,"materia":"civ","nivel":1,"enunciado":"Os pais podem emancipar o filho, por escritura pública, a partir dos:","opcoes":["16 anos","14 anos","12 anos","17 anos e meio"],"explicacao":"Art. 5º, parágrafo único, I, do Código Civil."},{"id":7247,"materia":"civ","nivel":1,"enunciado":"O casamento de um jovem de 17 anos, com autorização dos pais:","opcoes":["Faz cessar a incapacidade (emancipa)","Não muda nada na capacidade civil dele","Anula o casamento","Só vale aos 18"],"explicacao":"Art. 5º, parágrafo único, II."},{"id":7248,"materia":"civ","nivel":0,"enunciado":"Os pais respondem pelos danos causados pelos filhos menores que estão sob sua autoridade e companhia?","opcoes":["Sim, pela lei civil","Não, nunca","Só se forem casados","Só se o filho for maior de 16"],"explicacao":"Art. 932, I, do Código Civil."},{"id":7249,"materia":"civ","nivel":0,"enunciado":"Uma praça pública é um bem público de:","opcoes":["Uso comum do povo","Uso especial da administração","Uso dominical","Uso privado"],"explicacao":"Art. 99, I, do Código Civil."},{"id":7250,"materia":"civ","nivel":3,"enunciado":"A usucapião extraordinária ocorre, em regra, após posse sem oposição por:","opcoes":["15 anos","5 anos","2 anos","30 anos"],"explicacao":"Art. 1.238; o prazo cai para 10 anos se houver moradia ou obras."},{"id":7251,"materia":"civ","nivel":2,"enunciado":"Quem tem herdeiros necessários pode deixar em testamento, livremente, até:","opcoes":["Metade dos bens","Todos os bens","Um terço dos bens","Nada"],"explicacao":"A outra metade é a legítima (art. 1.789)."},{"id":7252,"materia":"civ","nivel":3,"enunciado":"Um contrato assinado sob ameaça grave (coação) é:","opcoes":["Anulável","Nulo de pleno direito","Válido sem ressalvas","Inexistente"],"explicacao":"Art. 171, II, do Código Civil."},{"id":7253,"materia":"civ","nivel":3,"enunciado":"Um negócio jurídico com objeto ilícito é:","opcoes":["Nulo","Anulável","Válido","Suspenso"],"explicacao":"Art. 166, II, do Código Civil."},{"id":7254,"materia":"pciv","nivel":0,"enunciado":"No processo, quem entra com a ação é o autor, e contra quem ela é proposta é o:","opcoes":["Réu","Juiz","Perito","Escrivão"],"explicacao":"As partes do processo."},{"id":7255,"materia":"pciv","nivel":1,"enunciado":"O prazo para apelar é de:","opcoes":["15 dias úteis","5 dias corridos","30 dias corridos","1 ano"],"explicacao":"Art. 1.003, § 5º, do CPC."},{"id":7256,"materia":"pciv","nivel":1,"enunciado":"Ana quer cobrar uma dívida de R$ 5 mil sem advogado. Ela pode procurar o Juizado Especial Cível, que dispensa advogado em causas de até:","opcoes":["20 salários mínimos","40 salários mínimos","60 salários mínimos","100 salários mínimos"],"explicacao":"Art. 9º da Lei 9.099/1995. O limite do Juizado é de 40 salários mínimos."},{"id":7257,"materia":"pciv","nivel":3,"enunciado":"O conciliador atua preferencialmente nos casos em que:","opcoes":["Não há vínculo anterior entre as partes","As partes são da mesma família","Há sociedade empresarial antiga","As partes são vizinhas há anos"],"explicacao":"O mediador atua quando há vínculo anterior (art. 165)."},{"id":7258,"materia":"pciv","nivel":2,"enunciado":"Quando não cabe mais recurso contra uma decisão de mérito, forma-se a:","opcoes":["Coisa julgada","Revelia","Preclusão lógica","Litispendência"],"explicacao":"Art. 502 do CPC."},{"id":7259,"materia":"pciv","nivel":2,"enunciado":"Quando há mais de um autor ou mais de um réu no mesmo processo, ocorre:","opcoes":["Litisconsórcio","Reconvenção","Revelia","Conexão"],"explicacao":"Art. 113 do CPC."},{"id":7260,"materia":"pciv","nivel":4,"enunciado":"No cumprimento de sentença, se o devedor não paga em 15 dias, o débito é acrescido de:","opcoes":["Multa de 10% e honorários de 10%","Multa de 50% sobre o valor da dívida","Juros de 1% ao dia","Nada"],"explicacao":"Art. 523, § 1º, do CPC."},{"id":7261,"materia":"arq","nivel":0,"enunciado":"Os documentos usados com frequência no dia a dia do setor ficam no arquivo:","opcoes":["Corrente","Permanente","Intermediário","Histórico"],"explicacao":"Primeira idade."},{"id":7262,"materia":"arq","nivel":1,"enunciado":"O instrumento que define por quanto tempo cada documento deve ser guardado e seu destino é a:","opcoes":["Tabela de temporalidade","Lista de presença dos servidores","Folha de ponto","Ficha de cadastro"],"explicacao":"Indica eliminação ou guarda permanente."},{"id":7263,"materia":"arq","nivel":0,"enunciado":"Arquivar as fichas dos clientes pela ordem dos sobrenomes é usar o método:","opcoes":["Alfabético","Numérico","Geográfico","Cronológico"],"explicacao":"Exemplo: SILVA, João."},{"id":7264,"materia":"arq","nivel":1,"enunciado":"Organizar os processos pelo número de cada um é usar o método:","opcoes":["Numérico","Alfabético","Geográfico","Ideográfico"],"explicacao":"Pode ser simples, cronológico ou dígito-terminal."},{"id":7265,"materia":"arq","nivel":2,"enunciado":"O material em que a informação é registrada, como papel ou disco, chama-se:","opcoes":["Suporte","Espécie","Tipo","Fundo"],"explicacao":"A informação é o conteúdo; o suporte é o meio."},{"id":7266,"materia":"arq","nivel":3,"enunciado":"Pelo princípio da proveniência, os documentos de uma instituição:","opcoes":["Não devem ser misturados com os de outras","Devem ser misturados por assunto com os de outros órgãos","Podem ser divididos à vontade","Devem ser eliminados após 5 anos"],"explicacao":"Também chamado de respeito aos fundos."},{"id":7267,"materia":"arq","nivel":4,"enunciado":"Nos arquivos permanentes, a organização dos documentos chama-se:","opcoes":["Arranjo","Classificação corrente","Protocolo","Expedição"],"explicacao":"Nos arquivos correntes fala-se em classificação."},{"id":7268,"materia":"arq","nivel":4,"enunciado":"O conjunto de documentos acumulados por uma mesma entidade é o:","opcoes":["Fundo","Dossiê","Item documental","Suporte"],"explicacao":"Unidade central do arranjo."},{"id":7269,"materia":"gest","nivel":1,"enunciado":"Na liderança democrática, as decisões são tomadas:","opcoes":["Com a participação do grupo","Só pelo líder, sem consulta","Pelo grupo, sem nenhuma orientação","Por sorteio"],"explicacao":"A autocrática centraliza; a liberal delega tudo."},{"id":7270,"materia":"gest","nivel":1,"enunciado":"Atingir o resultado esperado é eficácia. Fazer isso gastando menos recursos é:","opcoes":["Eficiência","Efetividade","Economicidade fiscal","Equidade"],"explicacao":"Eficiência é a relação entre recursos e resultados."},{"id":7271,"materia":"gest","nivel":2,"enunciado":"A administração pública gerencial tem foco em:","opcoes":["Resultados e no cidadão","Rituais e formalidades","Interesses pessoais do governante","Patrimônio do chefe"],"explicacao":"Surgiu como resposta ao excesso de burocracia."},{"id":7272,"materia":"gest","nivel":2,"enunciado":"São características da burocracia de Max Weber:","opcoes":["Impessoalidade, hierarquia e normas escritas","Improviso, favoritismo e cargos por indicação","Ausência de regras","Cargos herdados"],"explicacao":"Modelo racional-legal."},{"id":7273,"materia":"gest","nivel":2,"enunciado":"O patrimonialismo é marcado pela:","opcoes":["Confusão entre o público e o privado","Separação rigorosa entre as funções","Meritocracia","Transparência total"],"explicacao":"O governante trata o Estado como bem próprio."},{"id":7274,"materia":"prev","nivel":0,"enunciado":"A contribuição do empregado com carteira assinada para o INSS é descontada e recolhida:","opcoes":["Pelo empregador","Pelo próprio empregado, no banco","Pelo sindicato","Pela prefeitura"],"explicacao":"Vem descontada no contracheque."},{"id":7275,"materia":"prev","nivel":3,"enunciado":"O auxílio por incapacidade decorrente de acidente de trabalho:","opcoes":["Dispensa carência","Exige 180 contribuições","Exige 5 anos de empresa","Só é pago a servidores"],"explicacao":"Art. 26, II, da Lei 8.213/1991."},{"id":7276,"materia":"ia","nivel":2,"enunciado":"O STF usa uma ferramenta de inteligência artificial que ajuda a identificar recursos ligados a temas de repercussão geral. Ela se chama:","opcoes":["Victor","Watson","Siri","Alexa"],"explicacao":"Faz a triagem inicial; a decisão é sempre humana."},{"id":7277,"materia":"sust","nivel":3,"enunciado":"O CNJ exige dos tribunais um Plano de Logística Sustentável, que busca:","opcoes":["Reduzir o consumo de recursos e os impactos ambientais","Aumentar a impressão de processos em papel","Construir novos prédios","Trocar todos os servidores"],"explicacao":"Resolução CNJ 400/2021."},{"id":7278,"materia":"civ","nivel":1,"enunciado":"Na comunhão parcial, um apartamento que o marido herdou do pai durante o casamento:","opcoes":["Não se comunica, é só dele","Passa a ser dos dois","Vai para o Estado","É dividido com os sogros"],"explicacao":"Bens recebidos por herança ou doação ficam fora da comunhão (art. 1.659)."},{"id":7279,"materia":"civ","nivel":1,"enunciado":"Pela regra do Código Civil, a guarda dos filhos, quando os pais se separam e ambos estão aptos, é preferencialmente:","opcoes":["Compartilhada","Unilateral da mãe","Unilateral do pai","Dos avós"],"explicacao":"Art. 1.584, § 2º."},{"id":7280,"materia":"civ","nivel":1,"enunciado":"A convivência pública, contínua e duradoura, com objetivo de constituir família, caracteriza a:","opcoes":["União estável","Namoro qualificado","Sociedade de fato comercial","Adoção"],"explicacao":"Art. 1.723 do Código Civil."},{"id":7281,"materia":"civ","nivel":0,"enunciado":"Pela Lei 8.009/1990, o imóvel em que a família mora é, em regra:","opcoes":["Impenhorável (bem de família)","Sempre penhorável por qualquer dívida","Propriedade do banco","Bem público"],"explicacao":"Há exceções, como dívida do próprio imóvel."},{"id":7282,"materia":"civ","nivel":2,"enunciado":"A lei nova, quando não diz quando entra em vigor, começa a valer no Brasil depois de:","opcoes":["45 dias da publicação","Na data da publicação","90 dias","1 ano"],"explicacao":"Art. 1º da LINDB."},{"id":7283,"materia":"civ","nivel":3,"enunciado":"No exterior, quando admitida, a lei brasileira começa a valer, salvo disposição em contrário, depois de:","opcoes":["3 meses da publicação","45 dias, como no Brasil","6 meses","1 ano"],"explicacao":"Art. 1º, § 1º, da LINDB."},{"id":7284,"materia":"civ","nivel":3,"enunciado":"O juiz pode desconsiderar a personalidade jurídica para atingir os bens dos sócios em caso de:","opcoes":["Abuso, por desvio de finalidade ou confusão patrimonial","Qualquer dívida da empresa, mesmo sem abuso","Lucro baixo da empresa","Mudança de endereço"],"explicacao":"Art. 50 do Código Civil."},{"id":7285,"materia":"civ","nivel":2,"enunciado":"O fiador, em regra, tem o direito de exigir que primeiro sejam cobrados os bens do devedor. Esse é o benefício de:","opcoes":["Ordem","Inventário","Família","Divisão"],"explicacao":"Art. 827 do Código Civil."},{"id":7286,"materia":"civ","nivel":1,"enunciado":"Um prédio em que cada morador é dono do seu apartamento e todos dividem as áreas comuns é um:","opcoes":["Condomínio edilício","Comodato coletivo","Usufruto","Arrendamento"],"explicacao":"Art. 1.331 do Código Civil."},{"id":7287,"materia":"civ","nivel":2,"enunciado":"Quem tem o direito de usar um imóvel e receber os aluguéis dele, sem ser o dono, é o:","opcoes":["Usufrutuário","Nu-proprietário","Fiador","Comodante"],"explicacao":"Art. 1.394 do Código Civil."},{"id":7288,"materia":"civ","nivel":4,"enunciado":"Na sucessão, o cônjuge casado em comunhão parcial concorre com os descendentes:","opcoes":["Sobre os bens particulares do falecido","Sobre todos os bens comuns do casal","Nunca","Só se não houver filhos"],"explicacao":"Art. 1.829, I, conforme entendimento do STJ."},{"id":7289,"materia":"civ","nivel":2,"enunciado":"A transferência da propriedade de um bem móvel ocorre, em regra, com a:","opcoes":["Tradição (entrega)","Assinatura do contrato apenas","Escritura pública","Inscrição no cartório"],"explicacao":"Art. 1.267. Para imóveis, exige-se o registro."},{"id":7290,"materia":"civ","nivel":1,"enunciado":"O direito de passar pelo terreno do vizinho para chegar à via pública, quando o imóvel não tem saída, chama-se:","opcoes":["Passagem forçada","Usucapião","Servidão de vista","Comodato"],"explicacao":"Art. 1.285 do Código Civil."},{"id":7291,"materia":"pciv","nivel":1,"enunciado":"A sentença tem como elementos essenciais:","opcoes":["Relatório, fundamentos e dispositivo","Petição, contestação e réplica do autor","Citação, intimação e penhora","Título, capítulo e anexo"],"explicacao":"Art. 489 do CPC."},{"id":7292,"materia":"pciv","nivel":2,"enunciado":"Em regra, a citação no processo civil é feita:","opcoes":["Por meio eletrônico, conforme o CPC atual","Só por edital publicado no jornal","Só por oficial de justiça","Por telefone"],"explicacao":"Art. 246 do CPC, com a redação da Lei 14.195/2021."},{"id":7293,"materia":"pciv","nivel":2,"enunciado":"Cheque e nota promissória são exemplos de:","opcoes":["Títulos executivos extrajudiciais","Sentenças de primeiro grau","Petições iniciais","Recursos"],"explicacao":"Art. 784, I, do CPC."},{"id":7294,"materia":"pciv","nivel":2,"enunciado":"Em regra, o salário do devedor é:","opcoes":["Impenhorável","Penhorável por inteiro","Sempre bloqueado","Do credor"],"explicacao":"Art. 833, IV, com exceções, como dívida de alimentos."},{"id":7295,"materia":"pciv","nivel":3,"enunciado":"Contra a decisão de juiz de primeiro grau que concede tutela provisória, cabe:","opcoes":["Agravo de instrumento","Apelação","Embargos infringentes","Recurso especial"],"explicacao":"Art. 1.015, I, do CPC."},{"id":7296,"materia":"pciv","nivel":3,"enunciado":"O recurso extraordinário, que discute ofensa à Constituição, é julgado pelo:","opcoes":["STF","STJ","TRF","Juizado"],"explicacao":"Art. 102, III, da Constituição."},{"id":7297,"materia":"pciv","nivel":4,"enunciado":"Pelo CPC, as partes plenamente capazes podem ajustar mudanças no procedimento por meio de:","opcoes":["Negócio jurídico processual","Recurso adesivo combinado","Reconvenção","Embargos"],"explicacao":"Art. 190 do CPC."},{"id":7298,"materia":"pciv","nivel":1,"enunciado":"Quem tem a posse do sítio ameaçada por invasão pode propor:","opcoes":["Interdito proibitório","Ação de alimentos provisórios","Divórcio","Inventário"],"explicacao":"Ação possessória preventiva (art. 567 do CPC)."},{"id":7299,"materia":"pciv","nivel":2,"enunciado":"Se a posse já foi tomada à força, a ação possessória cabível é a de:","opcoes":["Reintegração de posse","Manutenção de posse","Interdito proibitório","Usucapião"],"explicacao":"Na turbação, cabe manutenção."},{"id":7300,"materia":"inf","nivel":1,"enunciado":"A Lei 11.419/2006 trata da:","opcoes":["Informatização do processo judicial","Lei de Acesso à Informação","Lei Geral de Proteção de Dados","Lei do Marco Civil da Internet"],"explicacao":"Permite processos eletrônicos."},{"id":7301,"materia":"inf","nivel":3,"enunciado":"No processo eletrônico, a petição enviada às 23h50 do último dia do prazo é:","opcoes":["Tempestiva, pois vale até as 24 horas","Intempestiva, pois o fórum fecha às 18h","Válida só no dia seguinte","Nula"],"explicacao":"Art. 3º, parágrafo único, da Lei 11.419/2006."},{"id":7302,"materia":"inf","nivel":2,"enunciado":"Pela Lei 11.419/2006, a intimação eletrônica se considera feita quando a parte consulta o teor ou, no máximo:","opcoes":["10 dias corridos após o envio","24 horas após o envio da intimação","30 dias úteis","No mesmo minuto do envio"],"explicacao":"Art. 5º, § 3º, da Lei 11.419/2006."},{"id":7303,"materia":"const","nivel":2,"enunciado":"O Superior Tribunal de Justiça é composto por, no mínimo:","opcoes":["33 ministros","11 ministros","27 ministros","15 ministros"],"explicacao":"Art. 104 da Constituição."},{"id":7304,"materia":"const","nivel":3,"enunciado":"O CNJ é presidido pelo:","opcoes":["Presidente do STF","Presidente da República","Procurador-Geral da República","Presidente do STJ"],"explicacao":"Art. 103-B, § 1º."},{"id":7305,"materia":"const","nivel":2,"enunciado":"O juiz de primeiro grau adquire a vitaliciedade após:","opcoes":["2 anos de exercício","3 anos de exercício","5 anos","6 meses"],"explicacao":"Art. 95, I, da Constituição."},{"id":7306,"materia":"const","nivel":2,"enunciado":"São garantias dos juízes: vitaliciedade, irredutibilidade de subsídio e:","opcoes":["Inamovibilidade","Imunidade penal total","Foro em qualquer tribunal","Direito a greve"],"explicacao":"Art. 95 da Constituição."},{"id":7307,"materia":"const","nivel":3,"enunciado":"Pelo quinto constitucional, um quinto dos lugares dos TRFs e TJs é ocupado por:","opcoes":["Membros do Ministério Público e advogados","Servidores concursados do tribunal","Deputados estaduais","Delegados de polícia"],"explicacao":"Art. 94 da Constituição."},{"id":7308,"materia":"const","nivel":3,"enunciado":"Ao juiz é vedado, entre outras coisas:","opcoes":["Dedicar-se a atividade político-partidária","Dar aulas como professor universitário","Votar nas eleições","Ter casa própria"],"explicacao":"Art. 95, parágrafo único, III. O magistério é permitido."},{"id":7309,"materia":"const","nivel":4,"enunciado":"O juiz que deixa o cargo só pode advogar no juízo ou tribunal do qual se afastou depois de:","opcoes":["3 anos","1 ano","5 anos","Nunca"],"explicacao":"É a quarentena (art. 95, parágrafo único, V)."},{"id":7310,"materia":"const","nivel":3,"enunciado":"A Justiça Eleitoral tem como órgãos o TSE, os TREs, os juízes eleitorais e as:","opcoes":["Juntas eleitorais","Varas do trabalho","Turmas recursais","Câmaras municipais"],"explicacao":"Art. 118 da Constituição."},{"id":7311,"materia":"const","nivel":3,"enunciado":"O Tribunal Superior do Trabalho é composto por:","opcoes":["27 ministros","11 ministros","33 ministros","15 ministros"],"explicacao":"Art. 111-A da Constituição."},{"id":7312,"materia":"adm","nivel":1,"enunciado":"Pela Lei 8.112/1990, depois de nomeado, o candidato aprovado tem para tomar posse:","opcoes":["30 dias","15 dias","60 dias","5 dias"],"explicacao":"Art. 13, § 1º."},{"id":7313,"materia":"adm","nivel":3,"enunciado":"O servidor que sofre limitação física e passa a exercer cargo compatível com ela é:","opcoes":["Readaptado","Reconduzido","Revertido","Redistribuído"],"explicacao":"Art. 24 da Lei 8.112/1990."},{"id":7314,"materia":"adm","nivel":2,"enunciado":"O deslocamento do servidor para outra unidade, no mesmo quadro, é a:","opcoes":["Remoção","Redistribuição","Reversão","Recondução"],"explicacao":"Art. 36 da Lei 8.112/1990."},{"id":7315,"materia":"gest","nivel":0,"enunciado":"Uma reunião em que todos dão ideias livremente, sem críticas na hora, é um:","opcoes":["Brainstorming","Benchmarking","Organograma","Fluxograma"],"explicacao":"Técnica de geração de ideias."},{"id":7316,"materia":"gest","nivel":0,"enunciado":"O desenho que mostra a estrutura hierárquica de um órgão, com seus setores, é o:","opcoes":["Organograma","Fluxograma","Cronograma","Histograma"],"explicacao":"O fluxograma mostra as etapas de um processo."},{"id":7317,"materia":"gest","nivel":2,"enunciado":"Na gestão de conflitos, a solução em que as duas partes saem ganhando é a:","opcoes":["Colaboração (ganha-ganha)","Evitação do conflito","Imposição","Acomodação"],"explicacao":"Busca atender aos interesses dos dois lados."},{"id":7318,"materia":"gest","nivel":3,"enunciado":"O princípio de Pareto (80/20) indica que:","opcoes":["Poucas causas costumam gerar a maior parte dos efeitos","Todos os problemas têm o mesmo peso","80% das metas falham","Só 20% dos servidores trabalham"],"explicacao":"Ajuda a priorizar ações."},{"id":7319,"materia":"arq","nivel":2,"enunciado":"Um documento que tem várias páginas reunidas sobre um mesmo assunto ou pessoa, como a pasta funcional de um servidor, forma um:","opcoes":["Dossiê","Fundo","Arranjo","Protocolo"],"explicacao":"Unidade documental composta."},{"id":7320,"materia":"arq","nivel":2,"enunciado":"Documentos de papel devem ser guardados em local com:","opcoes":["Temperatura e umidade controladas, longe da luz direta","Muito sol direto, para manter o papel seco","Umidade alta","Perto de produtos de limpeza"],"explicacao":"Evita mofo, fungos e desbotamento."},{"id":7321,"materia":"arq","nivel":3,"enunciado":"Os documentos de um órgão ordenados pelo assunto de que tratam seguem o método:","opcoes":["Ideográfico (por assunto)","Geográfico (por região)","Cronológico","Numérico simples"],"explicacao":"Pode ser alfabético ou numérico por assunto."},{"id":7322,"materia":"arq","nivel":4,"enunciado":"Na classificação de documentos, o método dígito-terminal ordena pelos:","opcoes":["Últimos dígitos do número","Primeiros dígitos","Nomes dos interessados","Estados de origem"],"explicacao":"Usado em grandes volumes de processos."},{"id":7323,"materia":"pen","nivel":0,"enunciado":"A testemunha que mente em juízo sobre fato importante do processo comete:","opcoes":["Falso testemunho","Calúnia contra a parte","Desacato","Estelionato"],"explicacao":"Art. 342 do Código Penal."},{"id":7324,"materia":"pen","nivel":2,"enunciado":"O falso testemunho deixa de ser punível se, antes da sentença no processo em que ocorreu, o agente:","opcoes":["Se retrata ou declara a verdade","Pede desculpas ao réu em audiência","Paga uma multa","Muda de cidade"],"explicacao":"Art. 342, § 2º, do Código Penal."},{"id":7325,"materia":"pen","nivel":2,"enunciado":"Mudar de lugar objetos do local do crime para enganar o perito ou o juiz é:","opcoes":["Fraude processual","Furto de provas","Dano","Prevaricação"],"explicacao":"Art. 347 do Código Penal."},{"id":7326,"materia":"pen","nivel":2,"enunciado":"O advogado que trai o dever profissional, prejudicando o cliente em juízo, comete:","opcoes":["Patrocínio infiel","Estelionato judicial","Prevaricação","Desacato"],"explicacao":"Art. 355 do Código Penal."},{"id":7327,"materia":"pen","nivel":3,"enunciado":"Quem se recusa a devolver os autos de um processo que retirou do cartório, como advogado, comete:","opcoes":["Sonegação de papel ou objeto de valor probatório","Furto de uso dos autos","Peculato","Nenhum crime"],"explicacao":"Art. 356 do Código Penal."},{"id":7328,"materia":"pen","nivel":1,"enunciado":"Fugir da prisão usando violência contra o carcereiro é crime de:","opcoes":["Evasão mediante violência contra a pessoa","Simples fuga, sem crime algum","Desobediência","Ameaça"],"explicacao":"Art. 352 do Código Penal."},{"id":7329,"materia":"pciv","nivel":2,"enunciado":"No Juizado Especial Cível, o recurso contra a sentença é julgado por:","opcoes":["Turma recursal formada por juízes de primeiro grau","Pelo STJ, em recurso especial","Pelo Tribunal do Júri","Pelo próprio juiz que sentenciou"],"explicacao":"Art. 41 da Lei 9.099/1995."},{"id":7330,"materia":"pciv","nivel":2,"enunciado":"No Juizado Especial Cível, o prazo para recorrer da sentença é de:","opcoes":["10 dias","15 dias","5 dias","30 dias"],"explicacao":"Art. 42 da Lei 9.099/1995."},{"id":7331,"materia":"pciv","nivel":3,"enunciado":"No Juizado Especial Cível, se o autor não comparece a nenhuma das audiências, o processo:","opcoes":["É extinto","Segue à revelia do autor","É enviado ao Ministério Público","É julgado procedente"],"explicacao":"Art. 51, I, da Lei 9.099/1995."},{"id":7332,"materia":"pciv","nivel":1,"enunciado":"Podem ser autores no Juizado Especial Cível, entre outros:","opcoes":["Pessoas físicas capazes e microempresas","Só grandes empresas e bancos","Órgãos públicos federais","Massas falidas"],"explicacao":"Art. 8º, § 1º, da Lei 9.099/1995."},{"id":7333,"materia":"port","nivel":2,"enunciado":"Ao se referir a um juiz que não é o destinatário do texto, mas de quem se fala, usa-se:","opcoes":["Sua Excelência","Vossa Excelência","Vossa Senhoria","Sua Majestade"],"explicacao":"\"Vossa\" é para quem se fala; \"Sua\", de quem se fala."},{"id":7334,"materia":"ia","nivel":0,"enunciado":"Ao usar uma ferramenta de IA para resumir um processo, o servidor deve:","opcoes":["Conferir as informações antes de usá-las","Copiar o resultado sem ler","Inserir dados sigilosos em qualquer site","Assinar como se fosse do juiz"],"explicacao":"A IA pode cometer erros e a responsabilidade é humana."},{"id":7335,"materia":"sust","nivel":2,"enunciado":"Substituir processos em papel por processos eletrônicos nos tribunais contribui para a sustentabilidade porque:","opcoes":["Reduz o consumo de papel, impressão e transporte","Aumenta o uso de energia sem nenhum benefício","Exige mais arquivos físicos","Gera mais lixo"],"explicacao":"É uma das metas dos planos de logística sustentável."},{"id":7336,"materia":"pcd","nivel":2,"enunciado":"Pelo Estatuto da Pessoa com Deficiência, a pessoa com deficiência tem direito, no processo judicial, a:","opcoes":["Recursos de acessibilidade e tecnologia assistiva","Julgamento sem necessidade de provas","Isenção de qualquer pena","Escolher o juiz"],"explicacao":"Art. 80 da Lei 13.146/2015."},{"id":7337,"materia":"civ","nivel":2,"enunciado":"Pelo Código Civil, a pessoa já pode fazer testamento a partir dos:","opcoes":["16 anos","18 anos","21 anos","14 anos"],"explicacao":"Art. 1.860, parágrafo único."},{"id":7338,"materia":"pciv","nivel":0,"enunciado":"Quem cumpre na rua as ordens do juiz, como citações, intimações e penhoras, é o:","opcoes":["Oficial de justiça","Escrivão do cartório","Perito","Conciliador"],"explicacao":"Art. 154 do CPC."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('civ','pciv','arq','gest','const','adm','pen','prev') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
